import React, { useState } from 'react';
import Modal from '../common/Modal';
import Badge from '../common/Badge';

const TaskReviewModal = ({ isOpen, onClose, onReview, task }) => {
  const [reviewNotes, setReviewNotes] = useState('');

  if (!task) return null;

  const handleAction = (action) => {
    onReview(task._id, { action, reviewNotes });
  };

  return (
    <Modal
      isOpen={isOpen}
      onClose={onClose}
      title={`Review Task Deliverable - ${task.taskId}`}
      maxWidth="650px"
    >
      <div style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
        <div style={{ background: 'var(--bg-input)', padding: '16px', borderRadius: '12px' }}>
          <div className="flex-row" style={{ justifyContent: 'space-between', marginBottom: '8px' }}>
            <h4 style={{ fontSize: '1.1rem', fontWeight: 700 }}>{task.taskTitle}</h4>
            <Badge text={task.taskStatus} />
          </div>
          <p style={{ fontSize: '0.875rem', color: 'var(--text-secondary)', marginBottom: '12px' }}>
            {task.description}
          </p>

          <div className="flex-row" style={{ gap: '20px', fontSize: '0.85rem' }}>
            <div>
              <span style={{ color: 'var(--text-muted)' }}>Project: </span>
              <strong>{task.project?.bookName}</strong>
            </div>
            <div>
              <span style={{ color: 'var(--text-muted)' }}>Task Amount: </span>
              <strong style={{ color: 'var(--success)' }}>₹{(task.taskPaymentAmount || 0).toLocaleString('en-IN')}</strong>
            </div>
            <div>
              <span style={{ color: 'var(--text-muted)' }}>Assigned: </span>
              <strong>{task.assignedTo?.map((u) => u.fullName).join(', ')}</strong>
            </div>
          </div>
        </div>

        {task.attachments && task.attachments.length > 0 && (
          <div>
            <h5 style={{ fontSize: '0.9rem', fontWeight: 700, marginBottom: '8px' }}>
              Uploaded Attachments:
            </h5>
            <div style={{ display: 'flex', flexDirection: 'column', gap: '6px' }}>
              {task.attachments.map((att, idx) => (
                <a
                  key={idx}
                  href={att.filePath}
                  target="_blank"
                  rel="noreferrer"
                  style={{
                    padding: '8px 12px',
                    background: 'var(--bg-card)',
                    border: '1px solid var(--border-color)',
                    borderRadius: '8px',
                    fontSize: '0.85rem',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'space-between',
                  }}
                >
                  <span>📄 {att.fileName}</span>
                  <span style={{ fontSize: '0.75rem', color: 'var(--primary)' }}>Download / View</span>
                </a>
              ))}
            </div>
          </div>
        )}

        <div className="form-group">
          <label className="form-label">Review Feedback / Approval Notes</label>
          <textarea
            className="form-textarea"
            rows="3"
            placeholder="Add review notes for employee..."
            value={reviewNotes}
            onChange={(e) => setReviewNotes(e.target.value)}
          />
        </div>

        <div className="modal-footer" style={{ padding: '16px 0 0 0', justifyContent: 'space-between' }}>
          <button
            type="button"
            className="btn btn-danger"
            onClick={() => handleAction('Rejected')}
          >
            Reject Submission
          </button>
          <div className="flex-row" style={{ gap: '10px' }}>
            <button type="button" className="btn btn-secondary" onClick={onClose}>
              Cancel
            </button>
            <button
              type="button"
              className="btn btn-primary"
              onClick={() => handleAction('Approved')}
            >
              Approve & Release Payment
            </button>
          </div>
        </div>
      </div>
    </Modal>
  );
};

export default TaskReviewModal;
